const Redis = require('ioredis');
const RedisStore = require('connect-redis').default;
var Log = require("@node-red/util").log;

const CHANNELS = {
    FLOW_REGISTERY: 'flow:registery',
    FLOW_UPDATE: 'flow:deploy:updates'
};

const EVENTS = {
    FLOWS_REGISTERY: 'flow:registery',
    FLOW_UPDATE: 'redis:flow:deploy:updates'
};

const FLOWS_REGISTERY_TYPES = {
    REGISTER: 'register',
    UNREGISTER: 'unregister',
    DELETE: 'delete'
}

// Create Redis client with options
const getRedisConfig = () => {
    if (process.env.REDIS_DEPLOYMENT_TYPE === 'single') {
        return {
            host: `${process.env.REDIS_HOST}`,
            port: parseInt(`${process.env.REDIS_PORT}`),
            maxRetriesPerRequest: null,
            prefix: `${process.env.REDIS_PREFIX}:`,
            keyPrefix: `${process.env.REDIS_PREFIX}:`,
            password: process.env.REDIS_PASS ? `${process.env.REDIS_PASS}` : null
        }
    }
    return getRedisClusterNodes()
}
const getRedisClusterNodes = () => {
    const clusterNodes = [];
    let i = 1;

    while (process.env[`REDIS_CLUSTERS_HOST_${i}`]) {
        const host = process.env[`REDIS_CLUSTERS_HOST_${i}`];
        const port = process.env[`REDIS_CLUSTERS_PORT_${i}`] || 6379; // Default to 6379 if PORT not specified

        clusterNodes.push({ host, port });
        i++;
    }

    return clusterNodes;
};

const getRedisInstance = () => {
    const config = getRedisConfig()
    if (`${process.env.REDIS_DEPLOYMENT_TYPE}` === 'single') {
        return new Redis(config);
    }

    const redisCluster = new Redis.Cluster(config, {
        scaleReads: 'all',
        redisOptions: {
            maxRetriesPerRequest: null,
            keyPrefix: `${process.env.REDIS_PREFIX}:`,
            password: process.env.REDIS_PASS ? `${process.env.REDIS_PASS}` : null
        }
    });
    return redisCluster;
};

const redisClient = getRedisInstance()

// Redis event handlers
redisClient.on('error', (err) => console.error('>>>>>>>>> Redis Client Error:', err));
redisClient.on('connect', () => console.log('>>>>>>>>> Redis Client Connected'));
redisClient.on('ready', () => console.log('>>>>>>>>> Redis Client Ready'));
redisClient.on('reconnecting', () => console.log('>>>>>>> Redis Client Reconnecting'));

// Create Redis session store
const redisStore = new RedisStore({
    client: redisClient,
    prefix: `${process.env.REDIS_PREFIX}:session:`,
    ttl: 86400, // Session TTL in seconds (1 day)
    disableTouch: false
});

const sessionConfig = {
    store: redisStore,
    secret: process.env.SESSION_SECRET,
    name: 'integration.sid',
    resave: false,
    saveUninitialized: false,
    rolling: false,
    cookie: {
        secure: process.env.NODE_ENV === 'production',
        httpOnly: true,
        maxAge: 24 * 60 * 60 * 1000, // 1 day
        sameSite: 'lax'
    }
};

// Add production security if running in production
if (process.env.NODE_ENV === 'production') {
    sessionConfig.cookie.secure = true; // Require HTTPS
    sessionConfig.proxy = true; // Trust the reverse proxy
}

class RedisChannelManager {
    constructor(redisClient) {
        if (RedisChannelManager.instance) {
            return RedisChannelManager.instance;
        }

        this.client = redisClient;
        this.subscriber = redisClient.duplicate();
        this.setupSubscriptions();

        RedisChannelManager.instance = this;
    }

    async setupSubscriptions() {
        try {
            await this.subscriber.subscribe(CHANNELS.FLOW_UPDATE);
            await this.subscriber.subscribe(CHANNELS.FLOW_REGISTERY);
            
            Log.info(`Subscribed to ${CHANNELS.FLOW_UPDATE} and ${CHANNELS.FLOW_REGISTERY}`);
            
            this.subscriber.on('message', (channel, message) => {
                if (channel === CHANNELS.FLOW_UPDATE) {
                    this.client.emit(EVENTS.FLOW_UPDATE, message);
                } else if (channel === CHANNELS.FLOW_REGISTERY) {
                    this.client.emit(EVENTS.FLOWS_REGISTERY, message);
                }
            });
        } catch (err) {
            Log.error("Failed to setup subscriptions:", err);
            throw err;
        }
    }

    async publish(channel, message) {
        try {
            await this.client.publish(channel, JSON.stringify(message));
        } catch (err) {
            Log.error(`Failed to publish to channel ${channel}:`, err);
            throw err;
        }
    }

    static getInstance(redisClient) {
        if (!RedisChannelManager.instance) {
            RedisChannelManager.instance = new RedisChannelManager(redisClient);
        }
        return RedisChannelManager.instance;
    }
}

const redisChannelManager = RedisChannelManager.getInstance(redisClient);

module.exports = {
    redisClient,
    sessionConfig,
    redisStore,
    getRedisConfig,
    redisChannelManager,
    CHANNELS,
    EVENTS,
    FLOWS_REGISTERY_TYPES
}; 